The rule: background cells not reachable from the border (enclosed by the marker color) become 3; the rest stay as-is.

```python
from collections import deque

def transform(grid):
    R, C = len(grid), len(grid[0])
    bg = 2  # not used directly; detect background as most common color
    from collections import Counter
    cnt = Counter(v for row in grid for v in row)
    bg = cnt.most_common(1)[0][0]
    seen = [[False]*C for _ in range(R)]
    q = deque()
    for r in range(R):
        for c in (0, C-1):
            if grid[r][c] == bg and not seen[r][c]:
                seen[r][c] = True; q.append((r, c))
    for c in range(C):
        for r in (0, R-1):
            if grid[r][c] == bg and not seen[r][c]:
                seen[r][c] = True; q.append((r, c))
    while q:
        r, c = q.popleft()
        for dr, dc in ((1,0),(-1,0),(0,1),(0,-1)):
            nr, nc = r+dr, c+dc
            if 0 <= nr < R and 0 <= nc < C and grid[nr][nc] == bg and not seen[nr][nc]:
                seen[nr][nc] = True; q.append((nr, nc))
    out = [row[:] for row in grid]
    for r in range(R):
        for c in range(C):
            if grid[r][c] == bg and not seen[r][c]:
                out[r][c] = 3
    return out
